parser = argparse.ArgumentParser(description='Build the standalone production methodologist guide.')
parser.add_argument('--capture-dir', required=True, type=Path)
parser.add_argument('--output', required=True, type=Path)
args = parser.parse_args()
ROOT = args.capture_dir.resolve()
TITLE = 'Kamilya LMS Инструкция методиста'
MARKS = {item['name']: item for item in json.loads((ROOT / 'marks.json').read_text(encoding='utf-8'))}
assert len(MARKS) == 24, 'Expected exactly 24 reviewed capture slots'
assert all(item['environment'] == 'production' and item['release_sha'] == '75d61a3857838f420d8ef8f4a7e3eb1bb270fac1' for item in MARKS.values()), 'Wrong capture environment or source'
CAPTIONS = {
'01-navigation': ('Где находятся основные разделы', ['«Документы» — загрузка и проверка готовности источников.', '«Создать курс из материалов» — выбор источников и генерация черновика.', '«Курсы» — проверка, редактирование, публикация и переход к назначению.', '«Назначения и доступ» — аудитория и способ входа. Сотрудники и журнал находятся ниже в меню; при необходимости прокрутите его.']),
'02-documents': ('Найдите источник в библиотеке', ['Откройте «Документы». Поиск помогает найти уже загруженный файл. Кнопка «Загрузить документ» находится вверху страницы; её форма показана следующим кадром.', 'Фильтр индексации отделяет готовые источники от обрабатываемых и проблемных.']),
'03-upload-form': ('Добавьте документ для курса', ['Нажмите область выбора файла или перетащите файл в неё. Допустимые форматы показаны здесь же.', 'Укажите понятное название с темой и редакцией, например «Приём залога действующая инструкция».', 'Для обычного курса выберите назначение «Материал для курса». Должностная инструкция — отдельный сценарий.', 'После выбора файла и заполнения обязательных полей нажмите «Загрузить документ». На этом снимке файл не выбран, поэтому кнопка неактивна.']),
'04-source-ready': ('Проверьте готовность и сохраните исходник для сверки', ['«Готов» означает готовность источника к использованию. При «Готов частично» сначала разберите предупреждение.', 'Кнопка скачивания открывает сохранённый исходник. Держите его рядом, когда проверяете уроки и вопросы.', 'При изменении инструкции используйте «Загрузить новую версию», а затем отдельно обновляйте курс. Старое обучение не переписывается автоматически.']),
'05-generate-source': ('Выберите материал для одного курса', ['Отметьте нужный источник. На снимке выбран один учебный документ. Для своего курса выберите материалы ломбарда, относящиеся к одной учебной задаче.']),
'06-generate-settings': ('Уточните настройки и запустите генерацию', ['Поле «Что должен дать курс» необязательно при обычной генерации. Рекомендуем описать действия, которым должен научиться сотрудник. Пример для ломбарда приведён ниже.', 'Аудитория тоже необязательна. Можно уточнить: новый оценщик без опыта работы по этой процедуре.', 'Для первого запуска можно оставить «Автоматически». Предлагаемый объём — ориентир, а не обещание точного количества уроков.', 'Выберите язык создаваемого курса. Это отдельная настройка от языка интерфейса.', 'Нажмите «Генерировать курс» после проверки выбора. Если кнопка неактивна, проверьте источники, общий замысел и очередь задач.']),
'07-course-list': ('Найдите полученный черновик в Курсах', ['У нового AI-черновика нажмите «Проверить», чтобы открыть редактор.', '«Редактировать» открывает содержание курса. На снимке справа уже опубликованный учебный курс.', '«Назначить сотрудникам» используется после проверки и публикации. У непроверенного черновика такого доступа для сотрудников нет.']),
'08-course-review': ('Одобрение курса и обязательное согласование', ['Сначала выберите каждый урок в структуре и проверьте его. На снимке намеренно проблемный учебный черновик, а не образец готового курса.', '«Одобрить курс» нажимайте только после проверки всех уроков и тестов. Для готового AI-курса после одобрения появится «Опубликовать». На текущем снимке эта кнопка ещё не должна отображаться.', 'Если политика требует рецензентов, откройте «Согласование» и завершите проверку актуальной версии. Не отключайте требование ради публикации.']),
'09-lesson-editor': ('Исправьте конкретный урок и сохраните изменения', ['Выберите нужный урок в структуре, а не изменяйте текст соседнего урока.', 'Отредактируйте содержание и сверяйте факты с исходником. Прокрутка внутри текстового поля и прокрутка всей страницы — разные действия.', 'Нажмите «Сохранить» после правки. Когда изменений нет, кнопка может быть неактивна. Изменённый урок требует повторной проверки его теста.']),
'10-lesson-preview': ('Читайте урок в виде, предназначенном сотруднику', ['Откройте нужный урок в структуре. Повторите проверку для каждого урока.', '«Предпросмотр» показывает учебный материал. Проверьте понятность, порядок действий, полноту и связь с источником.', '«Открыть как обучающийся» позволяет посмотреть учебное представление. Не сдавайте тест вместо сотрудника.']),
'11-quiz-review': ('Проверьте тест каждого урока', ['В «Тестах и вопросах» раскройте курс и выберите урок. У одного курса может быть несколько тестов — пройдите все.', 'Откройте «Изменить параметры», чтобы проверить проходной балл, время и число попыток.', 'Ниже находятся вопросы и варианты. Откройте «Редактировать» у каждого вопроса и сверяйте ключ с исходником.']),
'12-question-editor': ('Проверьте вопрос и правильный ответ', ['Исправьте формулировку. В ней должны быть все условия, необходимые для однозначного ответа.', 'Проверьте тип: один правильный вариант, несколько вариантов или верно/неверно. Он должен соответствовать заданию.', 'Сверьте пояснение с уроком и исходником. Оно не должно вводить новое правило.', 'Отметьте действительно правильный вариант. Просмотрите остальные варианты ниже: они должны быть правдоподобными, но неверными в заданных условиях.']),
'13-question-save': ('Сохраните исправленный вопрос', ['После проверки прокрутите окно вниз и нажмите «Сохранить». Помощник в этом же окне готовит предложения, но не заменяет вашу проверку и сохранение.', '«Отмена» закрывает окно без сохранения правок. Не путайте закрытие окна с сохранённым результатом.']),
'14-quiz-settings': ('Проверьте условия сдачи теста', ['Задайте проходной процент по правилам обучения компании. Число 80 на снимке — настройка учебного примера, не обязательная норма для ломбарда.', 'Проверьте ограничение времени. Пустое поле означает отсутствие ограничения. Не задавайте короткое время для длинного теста.', 'Укажите разрешённое число попыток. Продумайте, что делать сотруднику после неуспешной сдачи.', 'Нажмите «Сохранить» после изменения параметров. Эти параметры проверяются в редакторе теста, а не на экране предпросмотра.']),
'15-staff': ('Подготовьте состав сотрудников', ['Для первого запуска нажмите «Добавить сотрудника» и подготовьте одного обучающегося.', 'Для большого списка используйте вкладку «Импорт».', 'В «Структуре» проверьте подразделения, должности и принадлежность сотрудников. Не создавайте повторяющиеся названия из-за разного написания.']),
'16-staff-form': ('Добавьте сотрудника без дублей', ['Укажите табельный номер, имя и фамилию. Они должны относиться к одному человеку.', 'Укажите кадровый email для входа по email. Для человека без email можно использовать персональную ссылку и PIN.', 'Проверьте отдел и должность. При необходимости укажите новую должность; правила обучения могут автоматически создавать назначения.', 'Нажмите «Добавить» только после проверки полей. На снимке пустая форма — данные не отправлены.']),
'17-staff-import': ('Импортируйте штатное расписание с проверкой', ['Выберите Excel/CSV-файл штатного расписания для анализа.', 'Проверьте режим загрузки: показан «Добавить или обновить найденное». Автоматического удаления здесь нет.', 'Запустите анализ выбранного файла. Пока файл не выбран, кнопка неактивна.', 'Пройдите сопоставление колонок и предложение структуры. До подтверждения проверьте сотрудников, отделы, должности и дубли. Не подтверждайте весь импорт вслепую.']),
'18-assignment': ('Назначьте опубликованный курс', ['Выберите опубликованный курс слева. Непроверенный черновик в назначение не выдавайте.', 'Выберите способ доступа: email или персональная ссылка с PIN. На снимке показан PIN для сотрудника без email.', 'Отметьте нужного сотрудника. В режиме PIN выбирается один адресат; для email проверьте весь состав выбранной аудитории.', 'Нажмите «Назначить» после проверки курса, адресата и сроков. В инструкции показана заполненная форма, но назначение не отправлено.']),
'19-pin-deadlines': ('Не перепутайте три срока персонального доступа', ['Выберите «Персональная ссылка и PIN», если сотрудник входит по защищённой ссылке, в том числе с телефона без email.', 'Время после первого входа задаётся в минутах и начинает отсчитываться при первом открытии назначения. Пустое поле — без такого ограничения.', 'Срок ссылки в днях определяет, до какого момента можно начать вход. Он не означает, что после входа на курс даётся столько же дней.', '«Завершить до» — абсолютный крайний срок. Он действует вместе с предыдущими ограничениями. Учитывайте длину курса и рабочие смены.']),
'20-journal-filters': ('Найдите результат обучения конкретного сотрудника', ['Введите имя, email или табельный номер. Этот поиск не предназначен для названия курса.', 'Выберите статус, например «Завершён». При отсутствии результата проверьте и сбросьте лишние фильтры.', 'Включите историю, если нужно увидеть отменённые или заменённые назначения. Не смешивайте их с текущими.', '«Скачать CSV» выгружает выбранную выборку. Проверьте фильтры до выгрузки и передавайте файл только уполномоченным получателям.']),
'21-journal-record': ('Сверьте сотрудника и назначенный курс', ['Проверьте сотрудника, email и табельный номер. Однофамильцев различайте по кадровым данным.', 'Найдите нужный курс. Таблица широкая: прокрутите её горизонтально вправо к результату, сертификату и разбору ответов. Следующий кадр показывает ту же запись справа.']),
'22-journal-status': ('Разделяйте завершение и документальное подтверждение', ['Проверьте прогресс, лучший балл и дату завершения. Завершённый курс должен соответствовать правильному сотруднику и материалу.', 'Сертификат подтверждает завершение курса. Ожидаемый подписанный экземпляр или другое предусмотренное подтверждение проверяется отдельно.', '«Разбор ответов» показывает сохранённые попытки и помогает понять, где сотрудник ошибся или какой вопрос нужно пересмотреть.']),
'23-answer-review': ('Разберите попытку перед корректировкой обучения', ['Сверьте тест, дату попытки и версию материала. Снимок попытки относится к материалу, по которому сотрудник сдавал тест.', 'Посмотрите результат выбранной попытки, а не только общий прогресс курса.', 'Сопоставьте выбор сотрудника с ключом теста. Если ключ вызывает сомнение, проверьте вопрос по исходнику и исправляйте учебный материал, сохраняя историю попыток.']),
'24-quiz-approval': ('Явно одобрите проверенный AI-тест', ['Предупреждение означает, что тест требует проверки, в том числе после изменения урока. Сначала сопоставьте каждый ответ с материалом.', 'Нажмите «Одобрить после проверки» только после содержательной проверки. Одобрение курса не заменяет это действие. Показан сохранённый непроверенный QA-черновик — не образец одобренного курса.']),
}

FLOW_DATA = [
('sources','Подготовьте и загрузите источники','Возьмите актуальную утверждённую инструкцию на одну тему. Уберите лишние сведения клиентов. Проверьте сроки, исключения и приложения до загрузки.', ['02-documents','03-upload-form','04-source-ready'], 'Источник нужной редакции готов и доступен для содержательной сверки.', ['Не смешивайте старую и новую инструкции без ясного основания.','При ошибке обработки прочитайте сообщение и исправьте файл. Не запускайте повторную загрузку подряд.','При скане проверьте читаемость. Статус готовности не доказывает правильность будущего курса.']),
('generation','Сгенерируйте черновик курса','Откройте «Создать курс из материалов». Выберите документы одной учебной задачи. Цель и аудитория необязательны при обычной генерации, но помогают настроить учебную подачу. Генерация не публикует и не назначает курс.', ['05-generate-source','06-generate-settings'], 'В Курсах появился новый черновик который нужно проверить.', ['Для нескольких источников выберите одну группу либо явно подтвердите общую учебную цель. Если интерфейс требует решение о намеренном объединении разных материалов, укажите общий замысел не короче 20 символов. Предварительный допуск не доказывает смысловую совместимость всех правил.','После запуска следите за существующей задачей. Если она ещё выполняется, не создавайте повторную генерацию.','Если материала недостаточно, добавьте утверждённый источник или уточните цель. Не просите AI выдумать отсутствующее правило.']),
('lessons','Проверьте структуру и каждый урок','Найдите черновик в Курсах. Проверьте порядок модулей, затем все уроки по исходным документам. До сложного примера сотруднику должны быть объяснены обычный порядок и необходимые понятия.', ['07-course-list','10-lesson-preview','09-lesson-editor'], 'Все уроки прочитаны факты сверены правки сохранены.', ['Сверьте роли, порядок действий, сроки, числовые условия, исключения, запреты и обращение к руководителю.','Отличайте утверждённое правило от учебного примера. При противоречии документов сначала установите действующее основание.','После правки урока заново проверьте его тест. Проверка одного удачного урока не заменяет проверку всего курса.']),
('tests','Проверьте вопросы ответы и условия сдачи','В «Тесты и вопросы» раскройте нужный курс и последовательно проверьте тест каждого урока. Ответы должны следовать из материала и действующего источника.', ['11-quiz-review','12-question-editor','13-question-save','14-quiz-settings','24-quiz-approval'], 'Каждый тест содержательно проверен параметры понятны требуемое одобрение выполнено.', ['Вопрос должен содержать все условия для однозначного ответа. Проверьте каждый вариант и пояснение.','Не оставляйте правильный вариант узнаваемым только по длине, грамматике или нелепости остальных ответов.','Если урок изменился, разберите отметку «Требует проверки» и одобрите тест заново только после сверки.']),
('publication','Одобрите и опубликуйте готовый курс','Вернитесь в редактор после проверки уроков и тестов. Если обязательны рецензенты, завершите согласование актуальной версии. Затем одобрите AI-курс и выполните публикацию.', ['08-course-review'], 'Курс имеет статус Опубликован и готов к назначению.', ['«Одобрить курс» фиксирует проверку методистом. После него для готового AI-курса появится «Опубликовать». Это два отдельных действия.','При блокировке публикации прочитайте причину: непроверенный тест или незавершённое обязательное согласование нужно устранить, а не обходить.','После публикации проверьте статус в Курсах. Публикация ещё не выдаёт сотрудникам назначение.']),
('staff','Подготовьте сотрудников и структуру','Для пробного запуска добавьте одного сотрудника. При массовом запуске импортируйте список и проверьте принадлежность к филиалам, отделам и должностям.', ['15-staff','16-staff-form','17-staff-import'], 'Состав сотрудников проверен и не содержит случайных дублей.', ['Один кадровый email должен относиться к правильному сотруднику. Не создавайте второго человека ради повторной отправки доступа.','При импорте проверьте табельный номер, имя/фамилию или ФИО, отдел, должность и email. Не подтверждайте непроверенное сопоставление колонок.','Правила обучения могут создавать назначения при добавлении или обновлении сотрудников. Проверьте их результат прежде, чем назначать тот же курс вручную.']),
('assignment','Назначьте курс и выдайте личный доступ','Начните из опубликованного курса через «Назначить сотрудникам» либо из карточки сотрудника через «Назначить обучение». Проверьте курс, состав аудитории, способ входа и сроки перед подтверждением.', ['18-assignment','19-pin-deadlines'], 'Назначение есть у выбранного сотрудника и ему понятен способ входа.', ['Для email проверьте кадровый адрес и состояние доставки приглашения. Принятие письма сервисом отправки не означает, что сотрудник прочитал его.','В режиме PIN выбирайте одного сотрудника. Ссылка и PIN показываются один раз и передаются только адресату через согласованный канал. В инструкции секретные ссылки и PIN не воспроизводятся.','Тесты уроков доступны вместе с курсом — отдельно их не назначают. Для нового периода обучения используйте предусмотренное повторное назначение, а не удаление завершённого результата.']),
('results','Проверьте прохождение и разберите результаты','Попросите сотрудника войти по своему доступу, изучить все уроки, сдать обязательные тесты и выполнить «Завершить курс». Затем проверьте запись в Журнале обучения.', ['20-journal-filters','21-journal-record','22-journal-status','23-answer-review'], 'Первое пробное обучение сверено в журнале до массового запуска.', ['Различайте назначение, отправку приглашения, прогресс, успешную сдачу и завершение курса. Это разные состояния.','Если требуется подписанный экземпляр, найдите состояние подтверждения. Прикрепите полученный PDF/JPEG/PNG к правильной записи, проверьте читаемость и подписи, затем примите документ либо запросите замену с причиной. Загрузка сама по себе не означает принятие.','Сертификат, подтверждение кодом и подписанный документ не являются одним и тем же результатом. Используйте утверждённый в компании порядок оформления.']),
]

NORMALIZED = {}
for name, spec in MARKS.items():
    path = ROOT / 'screens' / f'{name}.jpg'
    w, h = Image.open(path).size
    dims = []
    for x, y, mw, mh in spec['marks']:
        if not spec['pixel']:
            x, mw, y, mh = x * w / 1280, mw * w / 1280, y * h / 720, mh * h / 720
        assert 0 <= x < w and 0 <= y < h and x + mw <= w + 1 and y + mh <= h + 1, (name, x, y, mw, mh, w, h)
        dims.append([round(x,2),round(y,2),round(mw,2),round(mh,2)])
    title, steps = CAPTIONS[name]
    assert len(steps) == len(dims), name
    NORMALIZED[name] = {'width':w,'height':h,'marks':dims,'sha256':hashlib.sha256(path.read_bytes()).hexdigest()}

def overlay(name):
    spec = NORMALIZED[name]
    parts = [f'<svg class="overlay" viewBox="0 0 {spec["width"]} {spec["height"]}" aria-hidden="true">']
    for idx, (x,y,w,h) in enumerate(spec['marks'],1):
        cx, cy = max(17,x - 4), max(18,y - 8)
        parts.append(f'<g data-spot="{name}-{idx}"><rect x="{x}" y="{y}" width="{w}" height="{h}" rx="5"/><circle cx="{cx}" cy="{cy}" r="15"/><text x="{cx}" y="{cy+5}" text-anchor="middle">{idx}</text></g>')
    return ''.join(parts) + '</svg>'

def figure(name, opened=False):
    title, steps = CAPTIONS[name]
    raw = (ROOT / 'screens' / f'{name}.jpg').read_bytes()
    data = 'data:image/jpeg;base64,' + base64.b64encode(raw).decode()
    spec = NORMALIZED[name]
    lines = [f'<details class="screen" id="screen-{name}" {"open" if opened else ""}><summary>{escape(title)}</summary><figure><div class="image-frame" data-image="{name}"><img src="{data}" width="{spec["width"]}" height="{spec["height"]}" alt="Реальный экран {escape(title)} с пронумерованными отметками" loading="lazy">{overlay(name)}</div><button type="button" class="zoom-button" data-zoom="{name}">Увеличить скриншот</button><figcaption>Номера на снимке соответствуют пояснениям ниже. Нажмите пояснение чтобы выделить нужное место.</figcaption></figure><ol class="legend">']
    for idx, step in enumerate(steps,1):
        lines.append(f'<li><button type="button" class="legend-button" data-highlight="{name}-{idx}" aria-pressed="false"><span class="number">{idx}</span><span>{escape(step)}</span></button></li>')
    return ''.join(lines) + '</ol></details>'

