parts.append('<section class="faq" id="questions"><h2>Если не получается</h2>'+''.join(f'<details><summary>{escape(a)}</summary><p>{escape(b)}</p></details>' for a,b in FAQ)+'</section><p class="footer">Инструкция помогает организовать внутреннее обучение. Для оформления результатов используйте утверждённый в компании процесс. Голосовой ввод и административные настройки в этот маршрут не входят.</p></main></div><div class="zoom" id="zoom" role="dialog" aria-modal="true" aria-labelledby="zoom-title" hidden><div class="zoom-toolbar"><span id="zoom-title">Реальный экран с отметками</span><button id="close-zoom" type="button">Закрыть · Esc</button></div><div class="zoom-content" id="zoom-content"></div><p class="zoom-note">На телефоне прокрутите большой снимок по горизонтали. Закройте его чтобы вернуться к пояснениям. Для изменения курса перейдите в свой кабинет.</p></div><script>'+SCRIPT+'</script></body></html>')

output = args.output.resolve()
output.parent.mkdir(parents=True, exist_ok=True)
output.write_text(''.join(parts),encoding='utf-8')
(ROOT/'guide.js').write_text(SCRIPT,encoding='utf-8')
(ROOT/'normalized-marks.json').write_text(json.dumps(NORMALIZED,ensure_ascii=False,indent=2),encoding='utf-8')
# Native SVG compositions for QA. Original JPEGs remain byte-for-byte unchanged.
qa = ROOT/'qa'
qa.mkdir(exist_ok=True)
for name, spec in NORMALIZED.items():
    image = base64.b64encode((ROOT/'screens'/f'{name}.jpg').read_bytes()).decode()
    svg = overlay(name).replace('class="overlay"', 'xmlns="http://www.w3.org/2000/svg"').replace('aria-hidden="true"', f'width="{spec["width"]}" height="{spec["height"]}"')
    svg = svg.replace('><g ', f'><style>rect{{fill:transparent;stroke:#b52d1e;stroke-width:2.5}}circle{{fill:#b52d1e;stroke:white;stroke-width:2}}text{{fill:white;font:bold 17px Arial,sans-serif}}</style><image href="data:image/jpeg;base64,{image}" width="{spec["width"]}" height="{spec["height"]}"/><g ',1)
    (qa/f'{name}.svg').write_text(svg,encoding='utf-8')
print(json.dumps({'output':str(output),'screens':len(NORMALIZED),'flows':len(FLOW_DATA),'bytes':output.stat().st_size,'sha256':hashlib.sha256(output.read_bytes()).hexdigest()},ensure_ascii=False))
